src='''from collections import Counter
def transform(grid):
    h,w=len(grid),len(grid[0])
    for i in range(h):
        if len(set(grid[i]))==1 and sum(x==grid[i][0] for row in grid for x in row)==w:
            panel=grid[i+1:]
            break
    else:
        for j in range(w):
            if len({row[j] for row in grid})==1 and sum(row[j]==grid[0][j] for row in grid)==h:
                panel=[row[j+1:] for row in grid]
                break
    counts=Counter(x for row in panel for x in row)
    background=counts.most_common(1)[0][0]
    return [[4 if x==background else 3 for x in row] for row in panel]
'''
